import {damageAttributeSummary} from './expedition-damage-attributes.mjs';
import {equipmentChangeView} from './expedition-equipment-change.mjs';
import {gradeArmorSummary} from './expedition-grade-armor.mjs';
import{equipmentWorkbenchView}from'./expedition-equipment-workbench.mjs';
import{lootAssignmentRehearsalView}from'./expedition-loot-rehearsal-view.mjs';
import{equipmentRequirementFailures,equipmentRequirementsView}from'./expedition-equipment-requirements.mjs';
import {equipmentRanksView} from './expedition-equipment-ranks-view.mjs';
import {lootReturnStatus} from './expedition-loot-transfer.mjs';
import {itemSetCollectionView,itemSetSummaryView,itemSetPieceLabel} from './expedition-item-sets-view.mjs';
import {equipmentSources} from './expedition-equipment-goal.mjs';
import {EQUIPMENT_SET_SLOTS} from './expedition-equipment-sets.mjs';
import {GEAR,SLOTS,equipmentName,equipmentTotals,gearSupports,gearRequirementName,replaceEquipment} from './expedition-equipment.mjs';
import {HEROES,ATTR,TYPES,SKILLS,DEFENSES,EXPEDITIONS} from './expedition-data.mjs';
import {gearDifference,isRelic} from './expedition-loot.mjs';
const itemImages={drawbow:'assets/items/drawbow-v231.svg',lamellarcoat:'assets/items/lamellarcoat-v227.svg',deepweave:'assets/items/deepweave-v227.svg',postbell:'assets/items/postbell.svg',filterveil:'assets/items/filterveil.svg'};
const itemArt=id=>Object.hasOwn(itemImages,id)?`<img class=equipment-art src="${itemImages[id]}" width="24" height="24" loading="lazy" decoding="async" alt="" aria-hidden="true">`:'';
export function equipmentImpact(plan,current,next){
 return equipmentSetImpact(plan,current,replaceEquipment(current,next));
}
export function equipmentSource(id){return equipmentSources(id).map(s=>s.label).join('；');}
export function equipmentStats(gear){const v=equipmentTotals(gear),grade=gradeArmorSummary(gear);return [`${grade?"基础护甲":"护甲"} ${v.armor}`,...Object.entries(v.bonus).map(([k,n])=>`${ATTR[k]} ${n>=0?'+':''}${n}`),...Object.entries(v.resistances).map(([k,n])=>`${TYPES[k]}抗性 ${n>=0?'+':''}${n}%`),...Object.entries(v.ranks||{}).map(([k,n])=>`${(k.startsWith('skill:')?SKILLS[k.slice(6)]:DEFENSES[k.slice(8)]).name}等级 ${n>=0?'+':''}${n}`),...(grade?[grade]:[]),...(damageAttributeSummary(gear)?[damageAttributeSummary(gear)]:[])].join(' · ');}
export function equipmentPanel(g,selected,filter,slot,plan,returnPreview=null,lootTrial=null,feedback='',warehouseItem='all',changeReceipt=null){
 const m=g.members.find(m=>m.id===selected),hero=HEROES.find(h=>h.id===selected);
 const stock=Object.entries(g.warehouse).filter(([,n])=>n>0),stockFilter=stock.some(([id])=>id===warehouseItem)?warehouseItem:'all';
 const options=()=>g.members.map(m=>`<option value="${m.id}" ${m.id===selected?'selected':''}>${HEROES.find(h=>h.id===m.id).name}</option>`).join('');
 const returnControl=id=>{const s=lootReturnStatus(g,selected,id);return `<div class="loot-return-control"><button data-loot-return="${id}" ${s.available?'':'disabled'}>归还共享仓库</button><small>${escapeSet(s.reason||'只回仓1件；不出售、不发金币或经验，之后可重新分配。')}</small></div>`;};
 const itemCard=(id,count)=>{const item=GEAR[id],owned=m.owned.includes(id),worn=m.gear[item.slot]===id,warehouse=count!==undefined,available=owned||!isRelic(id),disabled=!!g.pending||worn||(!owned&&(isRelic(id)||g.gold<60));const candidate=replaceEquipment(m.gear,id),requirements=equipmentRequirementFailures(m,candidate),impact=equipmentImpact(plan,m.gear,id);return `<article class="equipment-item"${warehouse?` data-warehouse-gear="${id}"`:` data-catalog-gear="${id}"`}><div><small>${SLOTS[item.slot]}${warehouse?' · 仓库 ×'+count:''}</small><h3>${itemArt(id)}${item.name}</h3><p>${equipmentStats(id)}</p>${equipmentRequirementsView(m,candidate)}${itemSetPieceLabel(id)?'<p>'+itemSetPieceLabel(id)+'</p>':''}<p>替换 ${GEAR[m.gear[item.slot]].name}：${gearDifference(m.gear,id)}</p>${item.slot==='weapon'?`<p>类别：${item.countsAs?gearRequirementName(item.countsAs):['bow','focus','lute'].includes(id)?gearRequirementName(id):'通用武器'}</p>`:''}${impact.length?`<p class="gear-warning">${impact.join('；')}</p>`:''}<small>来源：${equipmentSource(id)}</small></div><div class="bar">${warehouse?`<button data-assign="${id}" ${g.pending||owned?'disabled':''}>${owned?'此人已持有':'分配并装备'}</button><button data-loot-rehearse="${id}" ${g.pending||owned||!g.lineup.includes(selected)?'disabled':''}>试演分配</button><button data-sell="${id}" ${g.pending?'disabled':''}>出售1件 · 20金币</button>`:`<button data-equip="${id}" ${disabled||requirements.length?'disabled':''}>${worn?'已装备':owned?'换装':available?'购买并装备 · 60金币':'从仓库分配'}</button>${owned&&isRelic(id)?returnControl(id):''}`}</div></article>`;};
 return `<section class="guild-panel" data-guild-pane="equipment"><p class="eyebrow">固定属性 / 针对敌情配装</p><h2 id="equipment-overview" tabindex="-1">${hero.name}的装备</h2>${equipmentWorkbenchView(Object.values(g.warehouse).reduce((a,b)=>a+b,0))}<label>当前队员 <select id="gear-member">${options()}</select></label><button data-guild-tab="team">角色成长 →</button><p>每人各有武器、防具、饰品。换装只替换对应部位，原装备留在个人库。装备不限职业；技能仍受职业与武器类别约束。</p><div class="equipment-slots">${Object.entries(SLOTS).map(([key,label])=>`<article><small>${label}</small><h3>${itemArt(m.gear[key])}${GEAR[m.gear[key]].name}</h3><p>${equipmentStats(m.gear[key])}</p><button data-equipment-slot="${key}">挑选${label}</button></article>`).join('')}</div>${itemSetCollectionView(m,g.warehouse)}${equipmentRequirementsView(m)}${equipmentRanksView({...plan,id:m.id,gear:m.gear,training:m.training})}<p><b>合计</b> ${equipmentStats(m.gear)}。体质影响生命上限，智力和意志影响法力上限；抗性按伤害通道结算，攻防检定仍按攻击方式选择；例如远程攻防的潮印箭造成法术伤害。</p><h2 id="equipment-catalog-heading" tabindex="-1">挑选${hero.name}的装备</h2>${equipmentChangeView(changeReceipt)}<div class="bar"><label>部位 <select id="equipment-slot"><option value="all" ${slot==='all'?'selected':''}>全部部位</option>${Object.entries(SLOTS).map(([key,label])=>`<option value="${key}" ${slot===key?'selected':''}>${label}</option>`).join('')}</select></label><label>显示 <select id="gear-filter">${Object.entries({owned:'已持有装备',shop:'商店可购买',all:'全部装备与来源'}).map(([key,label])=>`<option value="${key}" ${filter===key?'selected':''}>${label}</option>`).join('')}</select></label></div><p>商店每件60金币，首次购买归个人持有，之后免费换装。同名装备属性固定，不生成随机词缀。下方差值按当前同部位计算；技能提醒覆盖默认及房间战术。</p>${returnPreview?lootReturnPreviewView(g,returnPreview):''}${lootAssignmentRehearsalView(lootTrial)}<div class="equipment-catalog">${Object.keys(GEAR).filter(id=>(slot==='all'||GEAR[id].slot===slot)&&(filter==='all'||(filter==='owned'?m.owned.includes(id):!isRelic(id)&&!m.owned.includes(id)))).map(id=>itemCard(id)).join('')||'<p>该筛选下暂无装备。</p>'}</div>${equipmentSetsView(g,selected,plan)}<h2 id="equipment-warehouse-heading" tabindex="-1"><img class="equipment-art" src="assets/items/warehouse-v195.svg" width="24" height="24" alt="" aria-hidden="true">战利品仓库</h2><label class="warehouse-recipient">分配给 <select id="warehouse-member">${options()}</select></label><label class="warehouse-recipient">查看库存 <select id="warehouse-item"><option value="all" ${stockFilter==='all'?'selected':''}>全部库存 · ${stock.reduce((n,[,count])=>n+count,0)}件</option>${stock.map(([id,n])=>`<option value="${id}" ${stockFilter===id?'selected':''}>${GEAR[id].name} ×${n}</option>`).join('')}</select></label>${feedback?`<p class="equipment-feedback" role="status">${escapeSet(feedback)}</p>`:''}<p>当前出战队员可在分配前试演两份完整战报；试演不消耗库存，候补请先安排出战。</p><p>当前分配给${hero.name}。分配消耗一件库存并立即装备；同名装备可留给其他成员，未穿戴、未被配装册引用的遗物可先回仓，再分给另一名队员；个人商店装备保持原规则。</p><div class="equipment-catalog">${stock.filter(([id])=>stockFilter==='all'||id===stockFilter).map(([id,n])=>itemCard(id,n)).join('')||'<p>暂无未分配装备。通关后领取奖励；可在“全部装备与来源”查看目标路线。</p>'}</div><button data-equipment-jump="overview">返回当前穿戴</button></section>`;
}

export function equipmentSetsView(g,id,plan){const m=g.members.find(m=>m.id===id);return `<section class=equipment-sets><h2 id="equipment-sets-heading" tabindex="-1">个人配装册</h2><p>四个栏位只保存此人已持有的三部位装备。保存不会换装；明确应用才一起替换，原装备保留、不买新装备、不改变训练、本人或伙伴职责。出征待结算时暂停修改。</p>${EQUIPMENT_SET_SLOTS.map(slot=>{const s=m.equipmentSets?.find(s=>s.slot===slot),impact=s?equipmentSetImpact(plan,m.gear,s.gear):[];return `<article data-equipment-set="${slot}"><label>栏${slot}名称 <input data-set-name="${slot}" maxlength=40 value="${escapeSet(s?.name||'')}" placeholder="例如：抗法或拆援" ${g.pending?'disabled':''}></label>${s?`<p>${equipmentName(s.gear)}</p><p>${equipmentStats(s.gear)}</p>${itemSetSummaryView(s.gear)}${equipmentRequirementsView(m,s.gear)}${impact.length?`<p class=gear-warning>${impact.join('；')}</p>`:''}`:'<p>尚未保存</p>'}<div class=bar><button data-set-save="${slot}" ${g.pending?'disabled':''}>${s?'以当前装备更新此栏':'保存当前装备'}</button>${s?`<button data-set-apply="${slot}" ${g.pending||equipmentRequirementFailures(m,s.gear).length?'disabled':''}>应用整套已持有装备</button><button data-set-delete="${slot}" ${g.pending?'disabled':''}>删除此栏</button>`:''}</div></article>`;}).join('')}</section>`;}
const escapeSet=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function equipmentSetImpact(plan,current,next){const changed=Object.values(next).reduce((gear,id)=>replaceEquipment(gear,id),current),skills=new Set(),defenses=new Set();for(const p of [plan,...Object.values(plan.overrides||{})]){for(const r of [...(p.prep||[]),...(p.main||[])])skills.add(r.skill);for(const id of Object.values(p.defenses||{}))defenses.add(id);}const result=[];for(const [ids,table]of [[skills,SKILLS],[defenses,DEFENSES]])for(const id of ids){const s=table[id],required=s.requiresGear||s.gear;if(required&&gearSupports(current,required)!==gearSupports(changed,required))result.push(`${s.name}：${gearSupports(changed,required)?'满足装备条件':'失去装备条件'}`);}return result;}

export function lootReturnPreviewView(g,preview){const s=lootReturnStatus(g,preview.heroId,preview.gearId);return `<section class="loot-return-preview" role="status"><h3>归还${escapeSet(s.gearName)}至共享仓库？</h3><p>持有人：${escapeSet(s.heroName)}。本次归还1件，仓库 ${s.warehouseBefore} → ${s.warehouseAfter}；确认后此人不再持有这件遗物。</p><p>不会出售或获得金币、经验；不会自动换装、更新配装栏或改写旧战报。回仓后仍需手动为另一名队员分配。</p>${s.available?'':`<p class="gear-warning">${escapeSet(s.reason)}</p>`}<div class="bar"><button data-loot-return-confirm=true ${s.available?'':'disabled'}>确认回仓1件</button><button data-loot-return-cancel=true>取消预览</button></div></section>`;}
